import{_ as t,o,c as r,ah as a}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Research: Walter Rosenkranz (Chairman of the Pilnacek Committee)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/walter-rosenkranz.md","filePath":"en/recherche/walter-rosenkranz.md"}'),n={name:"en/recherche/walter-rosenkranz.md"};function i(s,e,h,c,l,f){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="research-walter-rosenkranz-chairman-of-the-pilnacek-committee" tabindex="-1">Research: Walter Rosenkranz (Chairman of the Pilnacek Committee) <a class="header-anchor" href="#research-walter-rosenkranz-chairman-of-the-pilnacek-committee" aria-label="Permalink to &quot;Research: Walter Rosenkranz (Chairman of the Pilnacek Committee)&quot;">​</a></h1><p><strong>The new referee in the Archive of Silence.</strong></p><p>Walter Rosenkranz (FPÖ) has been President of the National Council since 2024 and, in this function, chairs the <strong>Pilnacek Committee of Inquiry</strong> (2025–2026). This places him in direct contrast to his predecessor, Wolfgang Sobotka (ÖVP), who is often at the center of the allegations in this committee.</p><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>Rosenkranz functions as the &quot;uncomfortable master of ceremonies&quot; in our mockumentary.</p><ul><li><strong>The Satirical Antagonist:</strong> He is the one who cuts off Sobotka&#39;s speech or plays the &quot;secret tapes&quot; in the plenary hall.</li><li><strong>Acoustic Clash:</strong> While Sobotka stands for the &quot;piano playing of power,&quot; Rosenkranz stands for the &quot;playing of the truth&quot; (or what the FPÖ considers it to be). In Part 4 of our screenplay, we use this clash for the grand finale in parliament.</li></ul><hr><p><em>Sources: Protocols of the National Council (2026), reporting on the committee inquiries (OE24, ORF, heute.at).</em></p>',9)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
